/* NVIDIA runtime, cuBLAS and cuRAND expose C APIs. No .cu or C++ compiler.
 * Covariance uses SGEMM; seeded Gaussian risk paths are generated by cuRAND.
 * This backend is a matrix/risk service, not a custom CUDA tick engine. */
#include "hft/api.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#ifdef HFT_HAVE_NVIDIA
#include <cublas_v2.h>
#include <cuda_runtime_api.h>
#include <curand.h>
void hft_nvidia_probe(HftCapability *cap) {
  int n = 0;
  memset(cap, 0, sizeof(*cap));
  strcpy(cap->name, "cuBLAS + cuRAND (C API)");
  cudaError_t rc = cudaGetDeviceCount(&n);
  cap->available = rc == cudaSuccess && n > 0;
  snprintf(cap->reason, sizeof(cap->reason), "%s",
           cap->available ? "NVIDIA risk/matrix libraries available"
                          : cudaGetErrorString(rc));
}
int hft_nvidia_risk(const float *x, int rows, int cols, float *covariance,
                    float *normals, int paths, hft_u64 seed, double *seconds,
                    char *error) {
  float *center = NULL, *device = NULL, *matrix = NULL, *random = NULL;
  int ok = 0;
  cublasHandle_t blas = NULL;
  curandGenerator_t rng = NULL;
  size_t count = (size_t)paths * cols;
  count += (count & 1);
  if (rows < 2 || cols < 1 || paths < 1)
    return 0;
  center = malloc((size_t)rows * cols * sizeof(float));
  if (!center)
    return 0;
  for (int j = 0; j < cols; ++j) {
    double mean = 0;
    for (int i = 0; i < rows; ++i)
      mean += x[i * cols + j] / rows;
    for (int i = 0; i < rows; ++i)
      center[i * cols + j] = (float)(x[i * cols + j] - mean);
  }
  double start = hft_now();
  if (cudaMalloc((void **)&device, (size_t)rows * cols * sizeof(float)) !=
          cudaSuccess ||
      cudaMalloc((void **)&matrix, (size_t)cols * cols * sizeof(float)) !=
          cudaSuccess ||
      cudaMalloc((void **)&random, count * sizeof(float)) != cudaSuccess)
    goto end;
  if (cudaMemcpy(device, center, (size_t)rows * cols * sizeof(float),
                 cudaMemcpyHostToDevice) != cudaSuccess ||
      cublasCreate(&blas) != CUBLAS_STATUS_SUCCESS ||
      curandCreateGenerator(&rng, CURAND_RNG_PSEUDO_PHILOX4_32_10) !=
          CURAND_STATUS_SUCCESS)
    goto end;
  float alpha = 1.0f / (rows - 1), beta = 0;
  /* Row-major T x N is column-major N x T. Product X * X^T is symmetric. */
  if (cublasSgemm(blas, CUBLAS_OP_N, CUBLAS_OP_T, cols, cols, rows, &alpha,
                  device, cols, device, cols, &beta, matrix,
                  cols) != CUBLAS_STATUS_SUCCESS ||
      curandSetPseudoRandomGeneratorSeed(rng, seed) != CURAND_STATUS_SUCCESS ||
      curandGenerateNormal(rng, random, count, 0, 1) != CURAND_STATUS_SUCCESS)
    goto end;
  if (cudaMemcpy(covariance, matrix, (size_t)cols * cols * sizeof(float),
                 cudaMemcpyDeviceToHost) != cudaSuccess ||
      cudaMemcpy(normals, random, (size_t)paths * cols * sizeof(float),
                 cudaMemcpyDeviceToHost) != cudaSuccess)
    goto end;
  *seconds = hft_now() - start;
  ok = 1;
end:
  if (!ok)
    strcpy(error, "NVIDIA allocation/library operation failed");
  if (rng)
    curandDestroyGenerator(rng);
  if (blas)
    cublasDestroy(blas);
  cudaFree(random);
  cudaFree(matrix);
  cudaFree(device);
  free(center);
  return ok;
}
#else
void hft_nvidia_probe(HftCapability *cap) {
  memset(cap, 0, sizeof(*cap));
  strcpy(cap->name, "cuBLAS + cuRAND (C API)");
  strcpy(cap->reason, "NVIDIA C libraries not compiled; install CUDA Toolkit "
                      "and configure HFT_NVIDIA=ON");
}
int hft_nvidia_risk(const float *x, int rows, int cols, float *cov,
                    float *normals, int paths, hft_u64 seed, double *seconds,
                    char *error) {
  (void)x;
  (void)rows;
  (void)cols;
  (void)cov;
  (void)normals;
  (void)paths;
  (void)seed;
  (void)seconds;
  strcpy(error, "NVIDIA C libraries not compiled");
  return 0;
}
#endif
